/* Northline Freight product kit. Every rule is scoped under .pf .lgx. */
.pf .lgx{
  --bg: #f6f7f9;
  --surface: #ffffff;
  --ink: #17202e;
  --muted: #4d5a6b;
  --line: #dde2e9;
  --line-strong: #c3cbd6;
  --accent: #b45309;
  --accent-strong: #8f3f06;
  --accent-soft: #f8eee6;
  --accent-ink: #ffffff;
  --ok: #17663a;
  --ok-soft: #e3f4ea;
  --warn: #8a4b00;
  --warn-soft: #fdefd6;
  --bad: #a3231f;
  --bad-soft: #fde7e5;
  --info: #1d4f91;
  --info-soft: #e4eefb;
  --radius: 10px;
  --radius-sm: 6px;
  --shadow: 0 1px 2px rgba(23, 32, 46, 0.06), 0 4px 12px rgba(23, 32, 46, 0.05);
  --font: "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, "Cascadia Mono", "SFMono-Regular", Consolas, monospace;
  font-family: var(--font);
  font-size: 14px;
  line-height: 1.45;
  color: var(--ink);
  background: var(--bg);
  min-height: 100%;
  box-sizing: border-box;
}
.pf .lgx *, .pf .lgx *::before, .pf .lgx *::after { box-sizing: border-box; }
.pf .lgx h1, .pf .lgx h2, .pf .lgx h3, .pf .lgx p { margin: 0; }
.pf .lgx a { color: inherit; text-decoration: none; }

/* app shell */
.pf .lgx .shell { display: grid; grid-template-columns: 216px 1fr; min-height: 100%; }
.pf .lgx .rail { background: var(--surface); border-right: 1px solid var(--line); padding: 16px 12px; display: flex; flex-direction: column; gap: 4px; }
.pf .lgx .rail-brand { display: flex; align-items: center; gap: 10px; padding: 4px 8px 16px; font-weight: 700; font-size: 15px; }
.pf .lgx .brand-mark { width: 28px; height: 28px; border-radius: 8px; background: var(--accent); color: var(--accent-ink); display: grid; place-items: center; font-size: 16px; }
.pf .lgx .rail-link { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: var(--radius-sm); color: var(--muted); font-weight: 500; }
.pf .lgx .rail-link:hover { background: var(--bg); color: var(--ink); }
.pf .lgx .rail-link.is-active { background: var(--accent-soft); color: var(--accent-strong); font-weight: 600; }
.pf .lgx .rail-foot { margin-top: auto; padding: 8px; color: var(--muted); font-size: 12px; }
.pf .lgx .main { display: flex; flex-direction: column; min-width: 0; }
.pf .lgx .topbar { display: flex; align-items: center; gap: 12px; padding: 12px 24px; background: var(--surface); border-bottom: 1px solid var(--line); }
.pf .lgx .topbar-title { font-weight: 600; font-size: 15px; }
.pf .lgx .topbar-search { margin-left: auto; display: flex; align-items: center; gap: 8px; min-width: 240px; padding: 7px 10px; border: 1px solid var(--line-strong); border-radius: var(--radius-sm); color: var(--muted); background: var(--bg); }
.pf .lgx .topbar-actions { display: flex; align-items: center; gap: 10px; }
.pf .lgx .icon-btn { width: 34px; height: 34px; display: grid; place-items: center; border: 1px solid var(--line); border-radius: var(--radius-sm); background: var(--surface); color: var(--muted); }
.pf .lgx .avatar { width: 32px; height: 32px; border-radius: 50%; background: var(--accent-soft); color: var(--accent-strong); display: grid; place-items: center; font-weight: 700; font-size: 12px; }
.pf .lgx .page { padding: 24px; display: flex; flex-direction: column; gap: 20px; }
.pf .lgx .page-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; }
.pf .lgx .page-title { font-size: 22px; font-weight: 700; letter-spacing: -0.01em; }
.pf .lgx .page-sub { color: var(--muted); margin-top: 2px; }

/* layout helpers */
.pf .lgx .grid { display: grid; gap: 16px; }
.pf .lgx .cols-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.pf .lgx .cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.pf .lgx .cols-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.pf .lgx .split { grid-template-columns: minmax(0, 2fr) minmax(0, 1fr); }
.pf .lgx .stack { display: flex; flex-direction: column; gap: 12px; }
.pf .lgx .row { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.pf .lgx .row-between { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.pf .lgx .spacer { flex: 1; }

/* cards */
.pf .lgx .card { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); box-shadow: var(--shadow); }
.pf .lgx .card-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 14px 16px; border-bottom: 1px solid var(--line); }
.pf .lgx .card-title { font-size: 14px; font-weight: 600; }
.pf .lgx .card-body { padding: 16px; }
.pf .lgx .card-foot { padding: 12px 16px; border-top: 1px solid var(--line); color: var(--muted); }
.pf .lgx .muted { color: var(--muted); }
.pf .lgx .mono { font-family: var(--mono); }
.pf .lgx .strong { font-weight: 600; }

/* stat tiles */
.pf .lgx .stat { background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); padding: 14px 16px; box-shadow: var(--shadow); display: flex; flex-direction: column; gap: 4px; }
.pf .lgx .stat-label { color: var(--muted); font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; }
.pf .lgx .stat-value { font-size: 26px; font-weight: 700; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
.pf .lgx .stat-delta { font-size: 12px; font-weight: 600; }
.pf .lgx .stat-delta.up { color: var(--ok); }
.pf .lgx .stat-delta.down { color: var(--bad); }

/* tables */
.pf .lgx .table-wrap { overflow-x: auto; }
.pf .lgx .table { width: 100%; border-collapse: collapse; }
.pf .lgx .table th { text-align: left; font-size: 12px; font-weight: 600; color: var(--muted); text-transform: uppercase; letter-spacing: 0.04em; padding: 10px 16px; border-bottom: 1px solid var(--line); background: var(--bg); white-space: nowrap; }
.pf .lgx .table td { padding: 12px 16px; border-bottom: 1px solid var(--line); vertical-align: middle; }
.pf .lgx .table tr:last-child td { border-bottom: 0; }
.pf .lgx .table tr.is-selected td { background: var(--accent-soft); }
.pf .lgx .table .num { text-align: right; font-variant-numeric: tabular-nums; }

/* forms */
.pf .lgx .form { display: flex; flex-direction: column; gap: 16px; }
.pf .lgx .field { display: flex; flex-direction: column; gap: 6px; }
.pf .lgx .label { font-weight: 600; font-size: 13px; }
.pf .lgx .input, .pf .lgx .textarea { width: 100%; padding: 9px 11px; border: 1px solid var(--line-strong); border-radius: var(--radius-sm); background: var(--surface); color: var(--ink); font: inherit; }
.pf .lgx .textarea { min-height: 84px; }
.pf .lgx .input:focus, .pf .lgx .textarea:focus { outline: 2px solid var(--accent); outline-offset: 1px; }
.pf .lgx .input.is-error { border-color: var(--bad); }
.pf .lgx .hint { color: var(--muted); font-size: 12px; }
.pf .lgx .error-text { color: var(--bad); font-size: 12px; font-weight: 600; }
.pf .lgx .check-row { display: flex; align-items: center; gap: 8px; }
.pf .lgx .check { width: 18px; height: 18px; border-radius: 4px; border: 1px solid var(--line-strong); display: grid; place-items: center; background: var(--surface); }
.pf .lgx .check.is-on { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
.pf .lgx .form-actions { display: flex; justify-content: flex-end; gap: 8px; padding-top: 4px; }

/* buttons */
.pf .lgx .btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 8px 14px; border-radius: var(--radius-sm); border: 1px solid var(--line-strong); background: var(--surface); color: var(--ink); font: inherit; font-weight: 600; cursor: pointer; }
.pf .lgx .btn:hover { background: var(--bg); }
.pf .lgx .btn-primary { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
.pf .lgx .btn-primary:hover { background: var(--accent-strong); }
.pf .lgx .btn-ghost { border-color: transparent; background: transparent; color: var(--accent-strong); }
.pf .lgx .btn-sm { padding: 5px 10px; font-size: 13px; }

/* chips and pills */
.pf .lgx .chip { display: inline-flex; align-items: center; gap: 6px; padding: 5px 12px; border-radius: 999px; border: 1px solid var(--line-strong); background: var(--surface); color: var(--muted); font-weight: 600; font-size: 13px; }
.pf .lgx .chip.is-on { background: var(--accent-soft); border-color: var(--accent); color: var(--accent-strong); }
.pf .lgx .pill { display: inline-flex; align-items: center; gap: 6px; padding: 2px 10px; border-radius: 999px; font-size: 12px; font-weight: 600; white-space: nowrap; }
.pf .lgx .pill-ok { background: var(--ok-soft); color: var(--ok); }
.pf .lgx .pill-warn { background: var(--warn-soft); color: var(--warn); }
.pf .lgx .pill-bad { background: var(--bad-soft); color: var(--bad); }
.pf .lgx .pill-info { background: var(--info-soft); color: var(--info); }
.pf .lgx .pill-muted { background: var(--bg); color: var(--muted); border: 1px solid var(--line); }

/* lists, meters, steps */
.pf .lgx .list { display: flex; flex-direction: column; }
.pf .lgx .list-item { display: flex; align-items: flex-start; gap: 12px; padding: 12px 16px; border-bottom: 1px solid var(--line); }
.pf .lgx .list-item:last-child { border-bottom: 0; }
.pf .lgx .list-icon { width: 32px; height: 32px; border-radius: 8px; background: var(--accent-soft); color: var(--accent-strong); display: grid; place-items: center; flex: none; }
.pf .lgx .list-main { flex: 1; min-width: 0; }
.pf .lgx .list-title { font-weight: 600; }
.pf .lgx .meter { height: 8px; border-radius: 999px; background: var(--line); overflow: hidden; }
.pf .lgx .meter-fill { height: 100%; background: var(--accent); border-radius: 999px; }
.pf .lgx .steps { display: flex; gap: 8px; }
.pf .lgx .step { flex: 1; padding: 8px 10px; border-radius: var(--radius-sm); border: 1px solid var(--line); background: var(--surface); color: var(--muted); font-weight: 600; font-size: 13px; }
.pf .lgx .step.is-done { border-color: var(--ok); color: var(--ok); }
.pf .lgx .step.is-current { border-color: var(--accent); background: var(--accent-soft); color: var(--accent-strong); }
.pf .lgx .kv { display: grid; grid-template-columns: 120px 1fr; gap: 8px 12px; }
.pf .lgx .kv dt { color: var(--muted); }
.pf .lgx .kv dd { margin: 0; font-weight: 600; }

/* empty state and toast */
.pf .lgx .empty { display: flex; flex-direction: column; align-items: center; text-align: center; gap: 6px; padding: 28px 16px; border: 1px dashed var(--line-strong); border-radius: var(--radius); color: var(--muted); }
.pf .lgx .empty-icon { width: 40px; height: 40px; border-radius: 50%; background: var(--accent-soft); color: var(--accent-strong); display: grid; place-items: center; font-size: 20px; }
.pf .lgx .empty-title { color: var(--ink); font-weight: 600; }
.pf .lgx .toast { display: flex; align-items: flex-start; gap: 10px; padding: 12px 14px; max-width: 360px; background: var(--ink); color: #ffffff; border-radius: var(--radius); box-shadow: 0 8px 24px rgba(23, 32, 46, 0.25); }
.pf .lgx .toast-title { font-weight: 600; }
.pf .lgx .toast-text { color: #d6dce5; font-size: 13px; }

/* meter widths, percentage steps of 5 */
.pf .lgx .w-5 { width: 5%; }
.pf .lgx .w-10 { width: 10%; }
.pf .lgx .w-15 { width: 15%; }
.pf .lgx .w-20 { width: 20%; }
.pf .lgx .w-25 { width: 25%; }
.pf .lgx .w-30 { width: 30%; }
.pf .lgx .w-35 { width: 35%; }
.pf .lgx .w-40 { width: 40%; }
.pf .lgx .w-45 { width: 45%; }
.pf .lgx .w-50 { width: 50%; }
.pf .lgx .w-55 { width: 55%; }
.pf .lgx .w-60 { width: 60%; }
.pf .lgx .w-65 { width: 65%; }
.pf .lgx .w-70 { width: 70%; }
.pf .lgx .w-75 { width: 75%; }
.pf .lgx .w-80 { width: 80%; }
.pf .lgx .w-85 { width: 85%; }
.pf .lgx .w-90 { width: 90%; }
.pf .lgx .w-95 { width: 95%; }
.pf .lgx .w-100 { width: 100%; }
@media (max-width: 860px) {
  .pf .lgx .shell { grid-template-columns: 1fr; }
  .pf .lgx .rail { flex-direction: row; overflow-x: auto; border-right: 0; border-bottom: 1px solid var(--line); }
  .pf .lgx .rail-foot { display: none; }
  .pf .lgx .cols-3, .pf .lgx .cols-4, .pf .lgx .split { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .pf .lgx .topbar-search { display: none; }
}
